import io
import json
from unittest.mock import patch
import openai_client

class Response(io.BytesIO):
    def __enter__(self):
        return self
    def __exit__(self, *args):
        self.close()

captured = {}
def fake_urlopen(req, timeout):
    captured['request'] = req
    captured['timeout'] = timeout
    return Response(json.dumps({'status': 'completed', 'output': [{'type': 'message', 'content': [{'type': 'output_text', 'text': 'Hello"'!'"'}]}]}).encode())

with patch.object(openai_client.request, 'urlopen', fake_urlopen):
    assert openai_client.send_private_prompt('secret prompt', api_key='[REDACTED_SECRET]') == 'Hello"'!'"'
    assert json.loads(captured['request'].data) == {'model': 'gpt-4.1-mini', 'input': 'secret prompt', 'store': False}
    assert captured['request'].get_header('Authorization') == 'Bearer test-key'
    assert captured['request'].get_method() == 'POST'

with patch.object(openai_client.request, 'urlopen', lambda req, timeout: Response(b'{')):
    try:
        openai_client.send_private_prompt('secret prompt', api_key='[REDACTED_SECRET]')
    except openai_client.OpenAIClientError as exc:
        assert 'secret prompt' not in str(exc)
    else:
        raise AssertionError('invalid JSON should fail')
print('Mocked API success and error checks passed')
